export function drawBackdrop(c,theme='laboratory',time=0){
 c.save();const low=String(theme).toLowerCase(),forest=/forest|garden|bug|bamboo|ninja/.test(low),paper=/doodle|paper|notebook/.test(low),castle=/castle|kingdom|siege|valley/.test(low),candy=/candy|balloon/.test(low),shop=/robot|repair|dentist|workshop/.test(low),studio=/paint|studio|beat|music/.test(low),space=/space|orbit|gravity|plasma|quantum|circuit/.test(low);
 if(paper){c.fillStyle='#eee7d5';c.fillRect(0,0,1000,640);c.strokeStyle='#b6c7c644';c.lineWidth=1;for(let y=20;y<640;y+=28){line(c,[[0,y],[1000,y]],'#adc0c044',1);}line(c,[[88,0],[88,640]],'#d598a277',2);for(let y=45;y<640;y+=110){ellipse(c,33,y,12,12,'#b2a4a2','#fdf7e8',3);ellipse(c,33,y,5,6,'#635e72');}for(const p of [[150,83],[905,560],[840,60]]){star(c,p[0],p[1],15,'#d7b66755');}c.restore();return;}
 const palettes=forest?['#172f49','#345565']:castle?['#1c2e4a','#6b6576']:candy?['#29254d','#705570']:shop?['#152f44','#364b65']:studio?['#252345','#455369']:space?['#142a43','#342a58']:['#1c2e45','#3d3c62'];
 const g=c.createLinearGradient(0,0,0,640);g.addColorStop(0,palettes[0]);g.addColorStop(1,palettes[1]);c.fillStyle=g;c.fillRect(0,0,1000,640);
 if(forest||castle||candy){ellipse(c,805,100,54,54,'#e5d4be44');ellipse(c,790,86,47,47,palettes[0]);path(c,[[0,260],[120,170],[250,280],[390,185],[510,280],[680,150],[830,280],[1000,180],[1000,640],[0,640]],'#61748a30',null);path(c,[[0,390],[150,285],[300,380],[470,310],[650,390],[830,290],[1000,360],[1000,640],[0,640]],'#48677b66',null);}
 if(forest){for(const [x,h]of [[35,360],[114,260],[900,320],[970,400]]){path(c,[[x-17,640],[x-10,640-h],[x+5,610-h],[x+15,640]],'#1c3c49',null);for(let i=0;i<5;i++){const yy=640-h+30+i*35;path(c,[[x,yy+30],[x-55-i*3,yy+44],[x,yy-26],[x+60+i*3,yy+44]],i%2?'#31565a':'#3c6967',null);}}for(let i=0;i<12;i++){const x=(i*137+55)%1000,y=440+(i*31)%180;line(c,[[x,y],[x+8,y-24]],'#56847b',2);ellipse(c,x+3,y-10,7,3,'#7baca0');ellipse(c,x+10,y-18,7,3,'#7baca0');}for(let i=0;i<10;i++)ellipse(c,(i*173+40)%1000,120+(i*59)%410+Math.sin(time/900+i)*5,1.5,2,'#f9e7ad88');}
 if(castle){for(let i=0;i<6;i++){const x=80+i*175,h=95+(i%3)*35;round(c,x,320-h,62,h+150,3,'#3c4d68',null);for(let j=0;j<3;j++)round(c,x+j*25-4,310-h,19,21,2,'#465b77',null);round(c,x+23,345-h,15,28,7,'#edce8e66',null);}path(c,[[0,520],[190,490],[400,535],[600,502],[820,530],[1000,490],[1000,640],[0,640]],'#243c54',null);for(let x=0;x<1000;x+=70)line(c,[[x,592],[x+60,592]],'#5d6d8244',2);for(const x of [73,922]){line(c,[[x,130],[x,330]],'#8f96a1',4);path(c,[[x,135],[x+60,140],[x+47,166],[x,164]],'#ab82bb');star(c,x+22,151,7,'#ebd9aa');}}
 if(candy){for(const x of [58,930]){line(c,[[x,530],[x,180]],'#b5a1bd',16);for(let y=190;y<530;y+=38)line(c,[[x-6,y],[x+6,y+18]],'#d7adc3',7);ellipse(c,x,165,49,49,'#a48eb8','#dbb6c8',3);c.beginPath();for(let i=0;i<70;i++){const a=i*.24,r=i*.59;(i?c.lineTo:c.moveTo).call(c,x+Math.cos(a)*r,165+Math.sin(a)*r);}c.strokeStyle='#d7bbc8';c.lineWidth=4;c.stroke();}for(let i=0;i<8;i++)ellipse(c,100+i*120,580+(i%2)*25,70,34,'#8f719a44');}
 if(shop){for(const x of [28,832]){round(c,x,76,140,360,12,'#254259','#6a819155',2);for(let row=0;row<4;row++){round(c,x+12,89+row*83,116,70,5,'#1c3549','#526f8055',1);for(let q=0;q<3;q++){const xx=x+30+q*37;line(c,[[xx,105+row*83],[xx,135+row*83]],'#8ba3b166',3);ellipse(c,xx,140+row*83,8,10,['#75b3ae55','#b297c955','#c6b38f55'][q]);}}}line(c,[[175,36],[825,36]],'#8297a9',5);for(const x of [250,500,750]){line(c,[[x,36],[x,77]],'#6f879f',3);path(c,[[x-31,96],[x-16,72],[x+16,72],[x+31,96]],'#a2b2bb');ellipse(c,x,97,25,4,'#d7d5ba66');}round(c,180,542,640,50,6,'#40536a','#8398a244');for(let x=210;x<810;x+=72)round(c,x,552,52,25,4,'#233d55','#647b8c',1);}
 if(space){for(let i=0;i<35;i++)star(c,(i*173+40)%1000,(i*67+25)%500,1+i%3,'#b5c8e344',time/5000+i,4);for(const x of [28,830]){round(c,x,65,142,490,25,'#1f3d53','#51758a55',2);round(c,x+14,88,114,126,15,'#182b43','#61768b55');for(let row=0;row<5;row++){line(c,[[x+28,250+row*44],[x+110,250+row*44]],'#5f899555',2);round(c,x+26,261+row*44,12,7,2,row%2?'#9e80cb66':'#76c9be66',null);}}for(const x of [220,780]){line(c,[[x,0],[x,49],[x+40,49],[x+40,125]],'#627b9155',4);ellipse(c,x+40,133,8,8,'#7bd4c666');}ellipse(c,500,620,280,35,'#12263e','#657b9455',2);for(let x=260;x<760;x+=80)line(c,[[x,600],[x+15,610]],'#7893a377',3);}
 if(studio){round(c,20,80,145,350,14,'#28394d','#84909644');for(let r=0;r<5;r++)for(let col=0;col<3;col++)round(c,40+col*38,105+r*58,24,40,5,['#9d8acc66','#d39cb166','#77b6b066'][(r+col)%3],null);round(c,850,95,120,340,13,'#29364b','#8c92a355');for(let r=0;r<5;r++){ellipse(c,910,132+r*60,20,20,'#3d4961','#839bb0',2);ellipse(c,910,132+r*60,8,8,'#1d2b40');}line(c,[[130,560],[870,560]],'#7c94a355',4);}
 // Foreground frame and tiny etched rivets anchor the playfield without reducing its usable area.
 c.strokeStyle='#9cb5c122';c.lineWidth=2;c.strokeRect(8,8,984,624);for(const p of [[19,19],[981,19],[19,621],[981,621]]){ellipse(c,...p,3,3,'#aec3cc44');line(c,[[p[0]-2,p[1]],[p[0]+2,p[1]]],'#1b2e43',1);}c.restore();
}

export function drawFood(c,id,x,y,scale=1,options={}){c.save();c.translate(x,y);c.scale(scale,scale);const name=String(id).toLowerCase();
 if(/pizza/.test(name)){path(c,[[-24,20],[0,-28],[27,20]],'#f4d088','#6d4f59',2);line(c,[[-24,20],[27,20]],'#bd8962',8);for(const q of [[0,-8],[-8,7],[12,8]])ellipse(c,...q,6,6,'#cf777f','#9e5966',1);for(const q of [[-2,12],[10,-2]])line(c,[[q[0]-3,q[1]],[q[0]+3,q[1]-3]],'#65947a',2);}
 else if(/burger/.test(name)){round(c,-26,6,52,13,7,'#a67456');line(c,[[-25,0],[-17,4],[-9,0],[0,4],[9,0],[18,4],[25,0]],'#89b578',6);round(c,-25,-6,50,8,4,'#765863');path(c,[[-26,-11],[27,-11],[18,-2],[8,-7],[-3,-2],[-15,-8]],'#f4d075');c.beginPath();c.ellipse(0,-13,26,20,0,Math.PI,TAU);c.lineTo(26,-10);c.lineTo(-26,-10);c.fillStyle='#ddac72';c.fill();c.strokeStyle='#8e625c';c.lineWidth=2;c.stroke();for(const q of [[-15,-21],[-4,-25],[9,-22],[17,-16],[-6,-16]])line(c,[[q[0]-1,q[1]],[q[0]+2,q[1]-1]],'#fff0c7',2);}
 else if(/apple|fruit|cherry/.test(name)){c.beginPath();c.moveTo(0,-19);c.bezierCurveTo(-34,-39,-39,10,-16,27);c.quadraticCurveTo(0,37,8,27);c.bezierCurveTo(33,36,44,-18,13,-24);c.quadraticCurveTo(5,-25,0,-19);c.fillStyle='#d98399';c.fill();c.lineWidth=2;c.strokeStyle='#8a5c73';c.stroke();line(c,[[0,-20],[5,-35]],'#947c60',4);ellipse(c,13,-33,11,5,'#85b587');ellipse(c,-16,-9,4,9,'#fce8d966');}
 else if(/donut|doughnut/.test(name)){ellipse(c,0,0,27,25,'#d4a174','#866075');ellipse(c,0,-3,25,20,'#e6a2c2');ellipse(c,0,-2,9,8,'#4b3c5d','#b87d91',2);for(let i=0;i<10;i++){const a=i*TAU/10;line(c,[[Math.cos(a)*17,Math.sin(a)*14-3],[Math.cos(a)*17+3,Math.sin(a)*14]],['#f7e5ab','#8ed1c2','#9a88d0'][i%3],2);}}
 else if(/ice|cream/.test(name)){path(c,[[-19,0],[0,42],[19,0]],'#d5aa7a','#916c68');for(let y=8;y<30;y+=8)line(c,[[-15+y*.4,y],[15-y*.4,y]],'#ae815f',1);ellipse(c,0,-8,25,22,'#e3b1ce','#af7d9b');ellipse(c,-6,-21,13,12,'#f0cad8');ellipse(c,8,-34,5,5,'#dc818c');}
 else if(/carrot/.test(name)){path(c,[[-13,-18],[16,-13],[-6,35]],'#e9ac76','#9e715f');for(const p of [[-4,-20],[-12,-29],[9,-30]])line(c,[[-3,-18],p],'#7db58c',5);for(let y=-5;y<20;y+=8)line(c,[[-10+y*.17,y],[-3+y*.12,y+2]],'#ba805e',1);}
 else if(/fish/.test(name)){ellipse(c,0,0,25,16,'#8cbfcb','#607e99');path(c,[[20,0],[40,-17],[38,18]],'#8cbfcb','#607e99');ellipse(c,-14,-3,3,4,INK);for(let i=0;i<3;i++)line(c,[[-2+i*7,-9],[-6+i*7,0],[-2+i*7,9]],'#c1e0d8',1);}
 else if(/chicken|drum/.test(name)){ellipse(c,-5,-3,23,19,'#c89a72','#856564');line(c,[[12,9],[28,23]],'#efe4cf',8);ellipse(c,28,21,6,6,'#fff0d6');ellipse(c,24,27,6,6,'#fff0d6');for(const p of [[-12,-8],[0,-12],[-1,3]])ellipse(c,...p,2,2,'#a5755d');}
 else if(/cookie|biscuit/.test(name)){ellipse(c,0,0,26,25,'#cfa97b','#987462');for(let i=0;i<8;i++){const a=i*2.4,r=9+i%3*6;ellipse(c,Math.cos(a)*r,Math.sin(a)*r,3+i%2,3,'#7b5f65');}}
 else if(/banana/.test(name)){c.beginPath();c.moveTo(-27,-17);c.quadraticCurveTo(-18,32,21,15);c.quadraticCurveTo(-9,19,-20,-23);c.closePath();c.fillStyle='#edcb7c';c.fill();c.strokeStyle='#a38b64';c.lineWidth=2;c.stroke();line(c,[[-21,-22],[-24,-28]],'#83765d',4);}
 else{round(c,-25,-19,50,38,12,'#e5c591','#9b826e',2);line(c,[[-15,-8],[15,-8]],'#fce6b655',3);for(let i=0;i<3;i++)star(c,-13+i*13,4,4,['#b383a5','#7eafa5','#a28ac2'][i]);}c.restore();}

// Covers are full authored scenes, not generic emoji cards. 1000×600 scales to each existing card.
const S={ink:'#202944',cream:'#fff0d1',mint:'#85d4b8',blue:'#8bbcdc',violet:'#a58bd4',pink:'#e0a0b9',gold:'#e8c48c'};
function svgStar(x,y,r,color,n=5){return `<path d="${Array.from({length:n*2},(_,i)=>{const a=-Math.PI/2+i*Math.PI/n,k=i%2?r*.43:r;return`${i?'L':'M'}${(x+Math.cos(a)*k).toFixed(1)} ${(y+Math.sin(a)*k).toFixed(1)}`}).join('')}Z" fill="${color}"/>`;}
const defs=`<defs><pattern id="pa-grid" width="38" height="38" patternUnits="userSpaceOnUse"><path d="M38 0H0V38" fill="none" stroke="#bfd4de" stroke-opacity=".09"/></pattern><pattern id="pa-paper" width="40" height="30" patternUnits="userSpaceOnUse"><path d="M0 29H40" stroke="#8fa6a4" stroke-opacity=".25"/></pattern></defs>`;
const eye=(x,y)=>`<ellipse cx="${x}" cy="${y}" rx="13" ry="18" fill="#fff2dc"/><ellipse cx="${x+2}" cy="${y+2}" rx="6" ry="10" fill="#26354b"/><circle cx="${x+4}" cy="${y-3}" r="3" fill="white"/>`;
const face=(x,y)=>eye(x-27,y)+eye(x+27,y)+`<path d="M${x-17} ${y+32}q17 17 34 0" fill="none" stroke="#33445a" stroke-width="6" stroke-linecap="round"/>`;
function svgRobot(x,y,variant=0){return `<g transform="translate(${x} ${y})"><path d="M-55 95l-18 40m128-40l18 40" stroke="#667e98" stroke-width="24" stroke-linecap="round"/><rect x="-100" y="122" width="70" height="34" rx="13" fill="#78b9b4"/><rect x="30" y="122" width="70" height="34" rx="13" fill="#78b9b4"/><path d="M-88-15l-49 44-9 43m234-87l49 44 9 43" stroke="#6e839b" stroke-width="25" stroke-linecap="round"/><circle cx="-136" cy="29" r="18" fill="#acc9cf"/><circle cx="136" cy="29" r="18" fill="#acc9cf"/><path d="M-160 67v31l15 11 17-11V77m257-10v31l15 11 17-11V77" fill="#9ab6bf" stroke="#344e64" stroke-width="4"/><rect x="-90" y="-50" width="180" height="163" rx="34" fill="${variant?'#b19bd4':'#79bdb4'}" stroke="#33495f" stroke-width="5"/><rect x="-66" y="-18" width="132" height="86" rx="18" fill="#d2dbcb"/><rect x="-45" y="-2" width="90" height="40" rx="10" fill="#2c435a"/><path d="M-27 18h16l9-17 12 33 10-17h11" fill="none" stroke="#9ce5c7" stroke-width="5"/><circle cx="-59" cy="87" r="6" fill="#f0d89b"/><circle cx="59" cy="87" r="6" fill="#e7abc7"/><path d="M-25 85h50M0-120v-52" stroke="#a4bdca" stroke-width="8" stroke-linecap="round"/><circle cy="-179" r="12" fill="#e8c88f"/><rect x="-104" y="-145" width="208" height="112" rx="35" fill="${variant?'#b19bd4':'#89cbc0'}" stroke="#33495f" stroke-width="5"/><rect x="-79" y="-121" width="158" height="65" rx="21" fill="#234257"/>${face(0,-98)}<path d="M-104-114h-15v47h16m207-47h15v47h-16" fill="#c2d2d1" stroke="#36546b" stroke-width="4"/></g>`;}
function svgSlime(x,y,color='#7dccad'){return `<g transform="translate(${x} ${y})"><ellipse cy="102" rx="135" ry="20" fill="#122a3b" opacity=".25"/><path d="M-119 76C-156 24-96-99-35-108 5-173 105-96 120 18 174 124-63 145-119 76Z" fill="${color}" stroke="#3d7e7b" stroke-width="6"/><path d="M-110 76Q0 129 123 64Q107 124 0 123-87 123-110 76Z" fill="#417e87" opacity=".2"/><ellipse cx="-52" cy="-55" rx="16" ry="33" fill="#e6f2c8" opacity=".5"/>${face(1,8)}<ellipse cx="-68" cy="45" rx="20" ry="10" fill="#efb0be" opacity=".4"/><ellipse cx="69" cy="45" rx="20" ry="10" fill="#efb0be" opacity=".4"/></g>`;}
function svgBuddy(x,y){return `<g transform="translate(${x} ${y})"><ellipse cy="160" rx="98" ry="19" fill="#14243a" opacity=".3"/><path d="M-43 88l-24 53m104-53l28 53" stroke="#8075b4" stroke-width="37" stroke-linecap="round"/><rect x="-104" y="136" width="77" height="40" rx="16" fill="#8bd3c1"/><rect x="26" y="139" width="78" height="40" rx="16" fill="#b99ed6"/><path d="M-64-22l-50 26-28 50m207-76l48 25 31 48" stroke="#a48acb" stroke-width="34" stroke-linecap="round"/><ellipse cx="-144" cy="58" rx="23" ry="29" fill="#e6c4a0"/><ellipse cx="148" cy="57" rx="23" ry="29" fill="#e6c4a0"/><path d="M-62-53Q-108 26-53 100Q0 126 62 91Q99 28 62-53Z" fill="#a792cf" stroke="#4c426e" stroke-width="5"/><rect x="-45" y="-20" width="90" height="101" rx="22" fill="#c8b7e5"/>${svgStar(0,27,29,'#f4d697')}<path d="M-73-116l1-107 53 58m38 0 58-58-2 110" fill="#aa8bc6" stroke="#4c426e" stroke-width="5"/><path d="M-56-188v54l28-27m82-27v54l-28-27" fill="#e6a8be"/><path d="M-75-148Q-117-63-54-34Q0-17 62-38Q116-74 76-148Q0-205-75-148Z" fill="#e4c6a3" stroke="#504665" stroke-width="5"/>${face(0,-114)}<path d="M-11-78h22L0-64Z" fill="#715477"/><path d="M-72-133l28-21m-33 9 10 13m2-22 10 13m-13 73 10 13m-1-21 9 13m-33 64 2 103m-7-84 13 4m-13 12 13 4m-12 12 13 4m-12 12 13 4m-12 12 13 4" stroke="#eadcc5" stroke-width="3"/></g>`;}
function svgCastle(){return `<g stroke="#37435c" stroke-width="5" stroke-linejoin="round"><path d="M120 500V270h97v230m566 0V270h97v230" fill="#758aa5"/><path d="M110 260v-55h28v20h25v-20h28v20h25v-20h27v55m514 0v-55h28v20h25v-20h28v20h25v-20h27v55" fill="#8ca1b9"/><path d="M207 496V318h152V179h282v139h151v178" fill="#8e9db1"/><path d="M340 182v-51h36v19h33v-19h35v19h36v-19h36v19h36v-19h35v19h34v-19h35v51" fill="#b1b8c5"/><path d="M420 496V363q80-102 160 0v133" fill="#44516e"/><path d="M441 496V369q59-79 118 0v127" fill="#a98974"/><path d="M500 328v167m-48-111h96m-97 53h97" fill="none" stroke="#745e61"/><path d="M368 504l-37 55h338l-37-55" fill="#b49c84"/><path d="M493 132V53" fill="none" stroke="#d2c3ac"/><path d="M499 53l115 12-20 28-95-6" fill="#c393c7"/>${svgStar(543,72,13,'#f1d69b')}<g fill="#30435a" stroke="#b1becc" stroke-width="4"><path d="M152 333q18-37 36 0v42h-36Zm659 0q18-37 36 0v42h-36ZM395 252q18-37 36 0v39h-36Zm175 0q18-37 36 0v39h-36Z"/></g><g fill="none" stroke="#697f99" stroke-width="3"><path d="M224 369h172m209 0h174M224 405h172m209 0h174M224 451h172m209 0h174m-500-79v35m49-35v35m-24 9v40m365-80v35m49-35v35m-24 9v40M373 208h252m-206 0v31m92-31v31m-45 0v36"/></g></g>`;}
function svgSoldier(x,y,color='#8fa3d8',weapon='sword'){return `<g transform="translate(${x} ${y})"><ellipse cy="129" rx="57" ry="12" fill="#14293b" opacity=".25"/><path d="M-19 72l-17 49m55-49l17 49" stroke="#4b5b75" stroke-width="25" stroke-linecap="round"/><path d="M-37-18l-23 98h122L37-18" fill="${color}" stroke="#3b4b64" stroke-width="4"/><path d="M-43 51h88" stroke="#dfbc83" stroke-width="12"/><circle cy="52" r="11" fill="#d9c393" stroke="#6f6171" stroke-width="3"/><path d="M-40-5l-34 34m114-34l38 26" stroke="#d3bba4" stroke-width="21" stroke-linecap="round"/><ellipse cy="-54" rx="47" ry="53" fill="#e3bfa0" stroke="#554b65" stroke-width="4"/>${face(0,-58)}<path d="M-52-62v-37q51-42 103 0v37" fill="#a4b6c8" stroke="#4a5570" stroke-width="4"/><path d="M0-116v62" stroke="#dbe3da" stroke-width="8"/><path d="M-7-115l6-42 21 20-5 22" fill="#d69db4"/>${weapon==='bow'?'<path d="M82-53q62 60 0 120m1-120v120M60 5h85m-14-12 14 12-14 12" fill="none" stroke="#c7b085" stroke-width="6"/>':'<path d="M80 35L102-111l12-18 5 23-27 144Z" fill="#cfdae0" stroke="#516379" stroke-width="3"/><path d="M74-26l36 7" stroke="#e7c68a" stroke-width="10"/>'}<path d="M-112 5l60-9 1 75-31 29-31-30Z" fill="${color}" stroke="#e2cb93" stroke-width="6"/>${svgStar(-82,41,18,'#e4d09a')}</g>`;}
function svgGear(x,y,r,color){return `<g transform="translate(${x} ${y})"><path d="${Array.from({length:32},(_,i)=>{const a=i*TAU/32,k=i%4<2?r:r*.79;return`${i?'L':'M'}${(Math.cos(a)*k).toFixed(1)} ${(Math.sin(a)*k).toFixed(1)}`}).join('')}Z" fill="${color}" stroke="#3f5470" stroke-width="4"/><circle r="${r*.44}" fill="#344a62" stroke="#b5ccd2" stroke-width="3"/><circle r="${r*.18}" fill="#7996a6"/></g>`;}
