export function drawMaterial(c,kind,x,y,w,h,options={}){
 c.save();c.translate(x,y);if(options.angle)c.rotate(options.angle);const k=String(kind).toLowerCase(),wood=/wood|beam|gate|bridge|roof/.test(k),ice=/ice|glass/.test(k),steel=/steel|metal|robot|cannon/.test(k);const base=options.color||(wood?'#b18a72':ice?'#94c7d4':steel?'#8b9eb3':'#8898ad');round(c,0,0,w,h,Math.min(6,h/4),base,'#32465f',Math.min(2,w/10));
 c.save();c.beginPath();c.rect(0,0,w,h);c.clip();
 if(wood){for(let yy=5;yy<h;yy+=12){c.beginPath();c.moveTo(0,yy);c.bezierCurveTo(w*.3,yy-4,w*.65,yy+5,w,yy);c.strokeStyle='#715c6355';c.lineWidth=1.3;c.stroke();}for(const xx of [5,w-5])for(const yy of [5,h-5])ellipse(c,xx,yy,1.8,1.8,'#5b5a65');if(w>30&&h>20){c.beginPath();c.ellipse(w*.63,h*.5,Math.min(w*.08,12),3,.1,0,TAU);c.strokeStyle='#7d606666';c.lineWidth=1;c.stroke();}}
 else if(ice){path(c,[[w*.04,h*.8],[w*.28,h*.05],[w*.52,h*.05],[w*.27,h*.95]],'#e6f5ed55',null);path(c,[[w*.5,h*.95],[w*.8,h*.05],[w*.92,h*.05],[w*.66,h*.95]],'#e6f5ed33',null);line(c,[[w*.7,h*.1],[w*.54,h*.36],[w*.65,h*.5],[w*.4,h*.8]],'#627e9e55',1);}
 else if(steel){for(const xx of [5,w-5])for(const yy of [5,h-5]){ellipse(c,xx,yy,2.5,2.5,'#c8d4d3','#50667e',1);line(c,[[xx-1.5,yy],[xx+1.5,yy]],'#50667e',1);}if(w>40){for(let xx=12;xx<w-10;xx+=9)line(c,[[xx,h*.35],[xx,h*.65]],'#3e526a44',1);}}
 else{const bh=Math.min(24,Math.max(12,h/3)),bw=bh*2;for(let yy=bh;yy<h;yy+=bh)line(c,[[0,yy],[w,yy]],'#52657d88',1.5);for(let row=0;row<Math.ceil(h/bh);row++)for(let xx=(row%2?bw/2:0);xx<w;xx+=bw)line(c,[[xx,row*bh],[xx,(row+1)*bh]],'#52657d88',1.5);for(let i=0;i<Math.min(20,w*h/250);i++){const xx=(i*43+11)%Math.max(1,w),yy=(i*29+7)%Math.max(1,h);line(c,[[xx,yy],[xx+2,yy+1]],'#d0d9d333',1);}}
 line(c,[[3,h-3],[3,3],[w-3,3]],'#f0ead34d',1.4);c.restore();if(options.damage){const d=Math.max(0,Math.min(1,options.damage));line(c,[[w*.48,0],[w*.4,h*.27],[w*.55,h*.43],[w*.42,h*.63],[w*.51,h]],'#35475e',1+d*3);}c.restore();
}

export function drawTool(c,tool,x,y,scale=1,options={}){
 c.save();c.translate(x,y);c.scale(scale,scale);c.rotate(options.angle||0);const k=String(tool).toLowerCase();
 if(/fan/.test(k)){ellipse(c,0,2,36,36,'#7596a6','#344e6b',3);for(let i=0;i<4;i++){c.save();c.rotate((options.time||0)/160+i*TAU/4);ellipse(c,0,-16,11,19,'#b6ddcc','#5f8f95',2);c.restore();}ellipse(c,0,0,7,7,'#f3d49e','#567c8f',2);round(c,-6,37,12,18,4,'#80abb1');round(c,-25,50,50,8,3,'#a2bdc1');}
 else if(/magnet/.test(k)){c.beginPath();c.moveTo(-21,-29);c.lineTo(-21,8);c.bezierCurveTo(-21,35,21,35,21,8);c.lineTo(21,-29);c.strokeStyle='#cb91ac';c.lineWidth=17;c.lineCap='butt';c.stroke();round(c,-30,-36,18,14,2,'#a6ccd3');round(c,12,-36,18,14,2,'#a6ccd3');for(const side of [-1,1])line(c,[[side*32,-17],[side*43,-28]],'#f6dba0',3);}
 else if(/bubble|waterballoon/.test(k)){for(const [x,y,r]of [[-17,12,20],[18,-13,25],[-17,-33,12]]){ellipse(c,x,y,r,r,'#9dcddd55','#c2e9e6',2);ellipse(c,x-r*.3,y-r*.35,r*.2,r*.3,'#f4f9df77');}}
 else if(/rocket/.test(k)){path(c,[[-14,20],[-14,-20],[0,-43],[14,-20],[14,20]],'#c8d6d0','#607b90',2);path(c,[[-14,7],[-29,29],[-11,22]],'#d19cb9');path(c,[[14,7],[29,29],[11,22]],'#d19cb9');ellipse(c,0,-10,9,12,'#91cbd5','#607c91',2);path(c,[[-9,24],[0,50],[9,24]],'#efd290');path(c,[[-4,24],[0,39],[4,24]],'#f2ac91',null);}
 else if(/trampoline|spring/.test(k)){ellipse(c,0,5,41,15,'#98bdb2','#567c85',3);line(c,[[-32,12],[-35,42]],'#c7c5b2',5);line(c,[[32,12],[35,42]],'#c7c5b2',5);for(let x=-25;x<=25;x+=12){line(c,[[x,2],[x-4,-8],[x+4,-15],[x-4,-22],[x,-30]],'#c5b6cf',2);}}
 else if(/glove/.test(k)){path(c,[[-22,9],[-27,-12],[-23,-30],[-12,-38],[10,-36],[22,-24],[24,-1],[17,19],[-8,25],[-22,9]],'#d99eb8','#755779',2);round(c,-16,21,33,18,5,'#c5a4d4','#765b8b');line(c,[[-9,-30],[7,-30]],'#f3c8d7',3);path(c,[[-21,-2],[-34,-6],[-38,2],[-24,17]],'#d99eb8','#755779',2);}
 else if(/screw|driver/.test(k)){round(c,-4,-43,8,52,2,'#bac8ce','#546a81',1);path(c,[[-4,-42],[-7,-54],[7,-54],[4,-42]],'#b8cad1','#546a81',1);round(c,-11,2,22,49,8,'#dda4ba','#775d83',2);for(const xx of [-5,5])line(c,[[xx,12],[xx,42]],'#aa7f9b',2);ellipse(c,0,8,7,3,'#edc0d0');}
 else if(/wrench|assembly/.test(k)){path(c,[[-5,44],[-9,-10],[-21,-22],[-21,-44],[-9,-33],[-1,-35],[5,-46],[15,-36],[14,-18],[3,-8],[7,44]],'#a2bac8','#516b83',2);ellipse(c,1,39,3,3,'#415c76');line(c,[[-2,-4],[2,29]],'#d6e4de',2);}
 else if(/wire/.test(k)){line(c,[[-30,30],[-25,5],[5,-2],[10,-27],[30,-32]],'#f1c08b',7);line(c,[[-30,30],[-25,5],[5,-2],[10,-27],[30,-32]],'#f6dcaa',2);round(c,-35,27,11,17,3,'#a2c0cc');round(c,27,-39,18,12,3,'#a2c0cc');for(const xx of [-32,-27])line(c,[[xx,44],[xx,50]],'#d9cfad',2);for(const yy of [-36,-31])line(c,[[45,yy],[52,yy]],'#d9cfad',2);}
 else if(/gear/.test(k)){const r=31;const p=[];for(let i=0;i<32;i++){const a=i*TAU/32,k=i%4<2?r:r*.78;p.push([Math.cos(a)*k,Math.sin(a)*k]);}path(c,p,'#d4bb8c','#7b6d78',2);ellipse(c,0,0,14,14,'#526a81','#eadab6',2);ellipse(c,0,0,6,6,'#9ab7be');}
 else if(/solder|laser/.test(k)){path(c,[[-5,-13],[0,-48],[5,-13]],'#b3c3ca','#536b83',1);round(c,-9,-15,18,13,3,'#d5c8b0','#6f7183');round(c,-11,-3,22,49,7,'#88b8ba','#4b7787');line(c,[[-5,7],[-5,34]],'#c0ded4',3);path(c,[[4,46],[13,56],[20,51],[29,58]],null,'#555a7a',4);if(options.active){star(c,0,-48,9,'#ffe2a2',options.time/100||0,4);}}
 else if(/brush|clean/.test(k)){round(c,-7,-3,14,48,6,'#94c5b4','#557f82');round(c,-15,-29,30,33,6,'#d5bc9c','#8b7e7e');for(let xx=-11;xx<15;xx+=5)line(c,[[xx,-26],[xx,-51+Math.abs(xx)*.35]],'#eee7cf',4);line(c,[[-11,-21],[11,-21]],'#9ba9b4',6);}
 else if(/battery/.test(k)){round(c,-21,-32,42,67,8,'#85b7b5','#4a7484');round(c,-9,-39,18,8,2,'#bcd0ce','#647f8e',1);round(c,-16,-18,32,44,4,'#2d5269','#bad3ca',1);path(c,[[3,-14],[-10,4],[0,4],[-3,20],[12,-1],[2,-1]],'#e8cf91',null);line(c,[[-13,-25],[-5,-25]],'#e1dbc3',2);line(c,[[6,-25],[14,-25]],'#e1dbc3',2);line(c,[[10,-29],[10,-21]],'#e1dbc3',2);}
 else if(/scan|diagnos/.test(k)){round(c,-27,-36,54,60,11,'#93b4c0','#4e7186');round(c,-20,-28,40,31,6,'#294a61','#bdd6cc',1);line(c,[[-15,-11],[-7,-11],[-3,-22],[4,-1],[10,-14],[15,-14]],'#8ae4c1',3);ellipse(c,0,13,5,5,'#e3c38e');round(c,-10,22,20,25,7,'#789fb3','#4e7186');if(options.active){for(let i=0;i<3;i++){c.beginPath();c.arc(0,-47,13+i*12,Math.PI*1.17,Math.PI*1.83);c.strokeStyle='#9fdbcc88';c.lineWidth=2;c.stroke();}}}
 else if(/water|spray/.test(k)){round(c,-15,0,30,43,8,'#83bacc','#496c8d');round(c,-11,-12,22,15,4,'#a8c8ce');path(c,[[-8,-11],[-8,-20],[23,-20],[23,-10],[6,-10]],'#d5c9b8','#6a7b8e');line(c,[[11,-8],[18,7]],'#b8d2d1',4);for(let i=0;i<3;i++){ellipse(c,28+i*7,-22-i*3,2,3,'#b0e4e4');}}
 else if(/hammer|glove/.test(k)){round(c,-6,-4,12,52,4,'#b6987b','#776a73');round(c,-29,-28,58,28,7,'#d3a1b6','#875f83');round(c,-25,-26,50,9,4,'#edc6d4',null);}
 else if(/cannon/.test(k)){round(c,-17,-36,34,63,7,'#899fb6','#3c5974');ellipse(c,0,-32,13,8,'#324e68','#c2c9cd',2);ellipse(c,-18,27,16,16,'#7e8caa','#b9c3cf',2);ellipse(c,18,27,16,16,'#7e8caa','#b9c3cf',2);}
 else{round(c,-18,-25,36,55,10,'#bba6d5','#7a7096');star(c,0,0,13,'#f1d79e');}c.restore();
}

/** Illustration anchored to an actual articulated Matter body. Width/height match that body. */
export function drawRagdollPart(c,part,x,y,w,h,angle=0,options={}){
 c.save();c.translate(x,y);c.rotate(angle);const unit=options.kind==='unit',u=options.unit||'club',f=String(options.faction||'').toLowerCase(),mage=['wizard','ice','fire','healer'].includes(u),rock=u==='golem',metal=u==='robot',slime=u==='slime',dragon=u==='dragon',color=options.color||(unit?'#8fa5ca':'#ae96d0');
 if(part==='head'){
  c.scale(w/60,h/60);
  if(!unit){path(c,[[-24,-12],[-24,-42],[-8,-23]],'#ac8bcc','#4f466d',1.5);path(c,[[8,-23],[25,-42],[24,-12]],'#ac8bcc','#4f466d',1.5);path(c,[[-21,-34],[-19,-18],[-13,-24]],'#e8acc2',null);path(c,[[21,-34],[13,-24],[19,-18]],'#e8acc2',null);}
  ellipse(c,0,0,29,29,unit?'#e6c1a4':'#e4c6a4',unit?'#5f526c':'#5b4b70',1.8);eyes(c,0,-3,11,options.expression||'happy');
  if(unit){
   if(mage){path(c,[[-31,-18],[-8,-55],[13,-29],[31,-18]],u==='fire'?'#ba8e9e':u==='ice'?'#91b7cc':u==='healer'?'#9dbb9f':'#a494c2','#6e6c94',1.5);ellipse(c,0,-17,34,5,u==='fire'?'#ba8e9e':u==='ice'?'#91b7cc':u==='healer'?'#9dbb9f':'#a494c2','#6e6c94',1.3);if(u==='healer'){line(c,[[-5,-39],[-5,-24]],'#e5dfbc',3);line(c,[[-12,-31],[2,-31]],'#e5dfbc',3);}else star(c,-3,-33,6,u==='ice'?'#d2e8dd':'#e9d3a1',0,4);path(c,[[-16,12],[0,39],[16,12],[7,17],[0,13],[-7,17]],'#d9ded0','#a0abb1',1);}
   else if(rock){path(c,[[-29,-8],[-26,-23],[-8,-34],[19,-28],[31,-9],[25,21],[7,30],[-25,20]],'#9baea6','#607f83',1.5);line(c,[[-17,-3],[-7,-2]],'#d7ddbc',4);line(c,[[8,-2],[18,-3]],'#d7ddbc',4);line(c,[[-6,15],[7,15]],'#5b7a7e',3);line(c,[[-16,-25],[-9,-13],[-15,-7]],'#6c8889',1);}
   else if(metal){round(c,-29,-25,58,49,12,'#96babd','#5f8494',1.5);round(c,-23,-15,46,25,7,'#345b70','#bdd9d0',1);eyes(c,0,-6,11,options.expression||'happy','#a8e4d3');line(c,[[0,-26],[0,-39]],'#a6c6c9',2);ellipse(c,0,-41,4,4,'#e4ca94');for(const sx of [-1,1])round(c,sx*30-3,-12,6,19,2,'#c4d2d0','#6b8d9d',1);}
   else if(slime){c.beginPath();c.moveTo(-25,15);c.bezierCurveTo(-39,-14,-16,-36,0,-24);c.bezierCurveTo(19,-43,42,8,24,22);c.quadraticCurveTo(0,35,-25,15);c.fillStyle='#94c2aa';c.fill();c.strokeStyle='#5d9487';c.lineWidth=1.5;c.stroke();eyes(c,0,-1,11,options.expression||'happy');ellipse(c,-14,-18,4,7,'#d9e9c780');}
   else if(dragon){path(c,[[-27,13],[-35,-5],[-26,-27],[-9,-22],[1,-31],[23,-25],[32,-2],[24,21]],'#96b9a9','#608e88',1.5);path(c,[[-24,-22],[-23,-44],[-9,-26],[9,-27],[23,-44],[25,-22]],'#d4c69d','#9e9b88',1);eyes(c,0,-2,12,options.expression||'happy');path(c,[[-21,15],[-35,7],[-27,24]],'#a6c6b4','#608e88',1);path(c,[[21,15],[35,7],[27,24]],'#a6c6b4','#608e88',1);}
   else if(u==='archer'||u==='slinger'){path(c,[[-29,1],[-29,-20],[0,-35],[29,-20],[29,1],[19,-13],[-19,-13]],color,'#637f90',1.5);line(c,[[-25,-8],[25,-8]],'#c7cfb5',2);}
   else if(u==='scout'||u==='lancer'||u==='cannon'){path(c,[[-23,-17],[-15,-34],[15,-34],[23,-17]],'#b7a18a','#8a7c80',1.5);ellipse(c,0,-16,36,5,'#b7a18a','#8a7c80',1.3);line(c,[[-17,-22],[17,-22]],color,3);}
   else if(u==='trickster'){path(c,[[-29,-8],[-31,-37],[-11,-26],[2,-43],[13,-23],[34,-34],[28,-7]],'#b19bc7','#7d749b',1.5);ellipse(c,-31,-37,4,4,'#dccb97');ellipse(c,2,-43,4,4,'#dccb97');ellipse(c,34,-34,4,4,'#dccb97');line(c,[[-24,-5],[24,-5]],'#59647f',7);eyes(c,0,-4,11,'angry');}
   else{path(c,[[-30,-4],[-29,-22],[0,-34],[29,-22],[30,-4],[19,-7],[19,-14],[-19,-14],[-19,-7]],u==='giant'?'#9e999a':'#a8b9c9','#53647c',1.5);line(c,[[0,-29],[0,-16]],'#e0e4d6',3);if(u==='axe'||u==='banner'||f.includes('viking')){path(c,[[-27,-23],[-42,-36],[-39,-15],[-27,-8]],'#d4c6a4','#9e978a',1);path(c,[[27,-23],[42,-36],[39,-15],[27,-8]],'#d4c6a4','#9e978a',1);}else path(c,[[-4,-32],[0,-50],[10,-41],[7,-32]],options.trim||'#d4a0bb',null);if(u==='knight')round(c,-26,-7,52,12,3,'#7a91a8','#c7d4d0',1);}
  }
  else{path(c,[[-4,9],[4,9],[0,14]],'#725476',null);stitch(c,-25,-10,-14,-20);round(c,21,-9,8,12,2,'#aacbc9','#6d8c98',1);ellipse(c,-20,10,6,3,'#ec9eb450');ellipse(c,20,10,6,3,'#ec9eb450');}
 }else if(part==='torso'||part==='body'){
  c.beginPath();c.moveTo(-w*.36,-h*.5);c.quadraticCurveTo(-w*.65,-h*.12,-w*.43,h*.4);c.quadraticCurveTo(0,h*.62,w*.43,h*.4);c.quadraticCurveTo(w*.65,-h*.12,w*.36,-h*.5);c.closePath();c.fillStyle=color;c.fill();c.strokeStyle=unit?'#425776':'#695981';c.lineWidth=Math.max(1,w*.035);c.stroke();
  round(c,-w*.32,-h*.28,w*.64,h*.7,w*.12,unit?'#d1d6c422':'#d3c1e4',unit?'#acc5c166':'#8f78ac',Math.max(1,w*.02));
  if(unit){
   if(rock){path(c,[[-w*.42,-h*.2],[-w*.1,-h*.45],[w*.38,-h*.2],[w*.44,h*.34],[0,h*.45],[-w*.46,h*.2]],'#91aaa3','#668889',Math.max(1,w*.03));star(c,0,0,w*.23,'#c8afd2',0,4);}
   else if(metal){round(c,-w*.39,-h*.35,w*.78,h*.7,w*.12,'#a8c4c3','#627f96',1);round(c,-w*.25,-h*.2,w*.5,h*.29,w*.05,'#335b71','#d2dfcb',1);line(c,[[-w*.16,-h*.08],[w*.15,-h*.08]],'#a5ddcd',Math.max(1,w*.04));}
   else if(slime){ellipse(c,0,0,w*.48,h*.5,'#92bda6','#5f9486',Math.max(1,w*.03));ellipse(c,-w*.19,-h*.2,w*.08,h*.1,'#d3e4c780');}
   else if(dragon){path(c,[[-w*.39,-h*.29],[-w*.95,-h*.5],[-w*.7,h*.16],[-w*.4,h*.25]],'#b3a5ca','#7f849e',1);path(c,[[w*.39,-h*.29],[w*.95,-h*.5],[w*.7,h*.16],[w*.4,h*.25]],'#b3a5ca','#7f849e',1);for(let yy=-h*.2;yy<h*.4;yy+=h*.2)line(c,[[-w*.27,yy],[w*.27,yy]],'#c8d7bc',Math.max(1,w*.03));}
   else{line(c,[[-w*.42,h*.2],[w*.42,h*.2]],'#cbb181',h*.1);round(c,-w*.1,h*.12,w*.2,h*.16,w*.04,'#dbc89d','#85767c',1);if(mage)star(c,0,-h*.05,w*.2,u==='ice'?'#c0e3df':u==='fire'?'#ecc39f':'#e2d1a3',0,4);else if(u==='guard'||u==='knight')path(c,[[-w*.2,-h*.29],[w*.2,-h*.29],[w*.17,0],[0,h*.1],[-w*.17,0]],'#c3cfcc','#7e9da9',1);else if(u==='banner')star(c,0,-h*.12,w*.17,'#e5d29b');}
  }
  else{star(c,0,h*.01,w*.22,'#f0d59d');stitch(c,-w*.4,-h*.25,-w*.38,h*.3);stitch(c,w*.4,-h*.25,w*.38,h*.3);}
 }else if(part==='hand'||part==='foot'){
  round(c,-w/2,-h/2,w,h,Math.min(w,h)*.35,part==='hand'?'#e2c5a3':color,part==='hand'?'#8d7380':'#617a89',Math.max(1,w*.035));line(c,[[-w*.25,h*.3],[w*.25,h*.3]],part==='hand'?'#bc9c91':'#dbded0',Math.max(1,w*.04));
 }else{
  round(c,-w/2,-h/2,w,h,Math.min(w,h)*.4,unit&&slime?'#9bc5ad':unit&&rock?'#9aafa8':unit&&metal?'#a5bec5':color,unit?'#4c617d':'#76618d',Math.max(1,w*.04));if(unit)round(c,-w*.4,-h*.17,w*.8,h*.34,Math.min(w,h)*.2,'#afbec8','#647c95',1);else stitch(c,-w*.21,-h*.3,-w*.21,h*.3);
 }
 c.restore();
}

const FOOD_NAMES={'🍞':'white','🥪':'wheat','🍔':'burger','🫓':'tortilla','🍕':'pizza','🥞':'pancake','🥩':'beef','🍗':'chicken','🐟':'fish','🥓':'bacon','🥚':'egg','🌭':'hotdog','🫘':'moonbean','🥬':'lettuce','🍅':'tomato','🧅':'onion','🥒':'cucumber','🫑':'pepper','🍄':'mushroom','🌿':'spinach','🧀':'cheddar','⚪':'mozzarella','🌈':'sprinkles','✨':'stardust','🟡':'mustard','🟤':'bbq','🌶️':'hot','🥛':'ranch','🧪':'slime','🍟':'fries','🍨':'icecream','🍦':'icecream','🥤':'shake','🍪':'cookie','🧁':'cupcake','💠':'crystal','🥕':'carrot','🥦':'broccoli','🍓':'strawberry','🍇':'grape','🍩':'donut','🍎':'apple','🍌':'banana','🍉':'watermelon','👾':'monstersnack','🥑':'avocado','🍿':'popcorn','🌮':'taco','🍊':'orange','🍍':'pineapple'};
const AVATAR_NAMES={'🦊':'fox','🐱':'cat','🐲':'dragon','🤖':'robot','🐼':'panda','🦄':'unicorn','🐯':'tiger','🐸':'frog','🐙':'octopus','🦁':'lion','🐰':'rabbit','👽':'alien','🦖':'dino','🐨':'koala','🐺':'wolf','🚀':'rocket','🦋':'butterfly','🐻':'bear','🦉':'owl','🦈':'shark','🧙':'wizard','🐧':'penguin','🪐':'planet','⭐':'star','🐶':'dog','🐵':'monkey','🐝':'bee','🐬':'dolphin','🐳':'whale','🦜':'parrot','🦔':'hedgehog','🦩':'flamingo','🦕':'sauropod','🦴':'bone','🥚':'egg','🐾':'paw','🌋':'volcano','🌴':'palm','🪨':'rock','🪺':'nest'};
const ICON_STROKE='stroke="#38455f" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"';
const oval=(x,y,rx,ry,fill,stroke='#4d536d')=>`<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" fill="${fill}" stroke="${stroke}" stroke-width="2"/>`;
